package dev.pedro.learning.ecommerce.notification.domain;import io.quarkus.hibernate.orm.panache.PanacheEntityBase;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="notification")public class NotificationEntity extends PanacheEntityBase{@Id public UUID id;@Column(name="order_id",nullable=false,unique=true)public UUID orderId;@Column(nullable=false)public String email;@Column(nullable=false)public int attempts;@Column(name="sent_at",nullable=false)public Instant sentAt;}